    out=R/'data/director/spell_proposals/persistent_damage_20_current_01.json'
    report=A/'PERSISTENT_DAMAGE_20_CURRENT_CHECK_01.json'
    assert not out.exists() and not report.exists()
    srcp=R/'data/director/spell_review/persistent_damage_20_source_convergence_01.json'; src=read(srcp)
