        sid=s['id']; oldrec=s['completeEarlierProposalUnchanged']; procedure=changes.get(sid,oldrec['procedure'])
        if sid in extra: procedure+='\n\n'+extra[sid]
        record={'id':sid,'name':s['name'],'riskTier':'B','status':'PENDING complete consolidated procedure; current original-case vector expansion still in progress','completeSourceAndAccess':deepcopy(s['completeCurrentSourceAndAccessUnchanged']),'procedure':procedure,'previousFullProposalUnchanged':deepcopy(oldrec),'previousSharedProposalUnchanged':deepcopy(s['completeEarlierSharedProposalUnchanged']),'sourcePromise':s['sourcePromiseToPreserve'],'remainingDecisions':s['remainingSemanticDecisions'],'damageRootProposal':deepcopy(next(x for x in roots['mapping'] if x['spellId']==sid)),'originalCaseIds':[c['id'] for c in src['originalCasesUnchanged'] if c['spellId']==sid]}
        ck('Full previous procedure/source exact '+sid,record['previousFullProposalUnchanged']==oldrec and record['completeSourceAndAccess']==s['completeCurrentSourceAndAccessUnchanged'])
        ck('Two original cases retained '+sid,len(record['originalCaseIds'])==2)
        records.append(record)
