    for doc in [src,findings,transfers,roots]:
        for b in doc['sourceBindings']:
            p=G/b['path']; ck('Source binding '+b['path'],info(p)=={k:b[k] for k in ['path','bytes','sha256']}); paths.add(p)
    for entry in interfaces: paths.add(G/entry['completeEntryUnchanged']['currentAuthoritativeSource']['path'])
    bindings=[info(p) for p in sorted(paths)]
    examples=[deepcopy(findings['proposedSourceFixture'])]+deepcopy(transfers['vectors'])+deepcopy(roots['vectors'])
    pending=[{'id':'P20-Q'+str(i+1).zfill(2),'spellId':s['id'],'question':s['remainingSemanticDecisions'],'status':'Requires actual GPT source-linked semantic disposition','proposedDirection':'Use complete current procedure and explicit root mapping; preserve all prior text and NEW status.'} for i,s in enumerate(src['spells'])]
    value={'id':'PERSISTENT-DAMAGE-20-CURRENT-01','recordedAtUtc':datetime.now(timezone.utc).isoformat(),'status':'UNSENT consolidated video-game authorship; original-case digital vectors still in development; not review-ready or adopted','riskScope':'20 interaction-heavy identities, 21 actual placements. Any global rule expansion remains separate systemic work.','previousSourceAudit':info(srcp),'sharedRules':shared,'spells':records,'originalExamplesUnchanged':deepcopy(src['originalCasesUnchanged']),'currentSupplementalExamples':examples,'currentExampleCoverageStatus':{'originalCount':40,'fullOriginalTextsPreserved':40,'originalCaseDigitalExpansionComplete':False,'supplementalExamples':len(examples),'scope':'Named lawful-source composition and root vectors only; do not count as 40 fully current original scenarios or runtime tests.'},'currentInterfaceEntries':interfaces,'openQuestions':pending,'sourceLinkedFindingsUnchanged':deepcopy(findings['findings']),'pendingDependencies':[{'source':'DE4 Current06/Fate04','scope':'Actual narrow follow-up active. Rebind exact outcome after acceptance; no implied new Fate disclosure for these spell draws.'},{'source':'Damage/control25 Current06','scope':'Mixed-type aggregate reduction proposal remains unsent, pending and source-scoped. Ice Storm requires its own explicit agreement; do not substitute a global pipeline.'},{'source':'Environment foundations local draft01','scope':'No implicit approval of general spreading fire, structural simulation or broader physical hazard system.'}],'sourceBindings':bindings,'acceptedCountsUnchanged':{'reviewed':465,'pending':383},'newRuleAdoptions':0,'runtimeTestsExecuted':0,'sourceInformationDeleted':0}
